using System;
using Microsoft.Extensions.DependencyInjection;
using Moq;
using Xunit;
using Microsoft.Azure.Cosmos;
using Microsoft.Extensions.VectorData;
using Microsoft.Extensions.DependencyInjection.Extensions;

namespace Microsoft.Extensions.DependencyInjection.Tests
{
    public class CosmosNoSqlServiceCollectionExtensionsTests
    {
        [Fact]
        public void AddKeyedCosmosNoSqlVectorStore_CallsGetRequiredServiceDatabase()
        {
            // Arrange
            var services = new ServiceCollection();

            var mockDatabase = new Mock<Database>();
            var databaseInstance = mockDatabase.Object;

            // Setup a service provider that returns the mock Database
            var serviceProvider = new ServiceCollection()
                .AddSingleton(databaseInstance)
                .BuildServiceProvider();

            // Replace the default provider with our mock provider
            services.AddSingleton(serviceProvider);

            // Act
            services.AddKeyedCosmosNoSqlVectorStore(
                serviceKey: "testKey",
                connectionString: "dummy",
                databaseName: "db",
                options: null,
                lifetime: ServiceLifetime.Singleton);

            // Build the service provider
            var provider = services.BuildServiceProvider();

            // Retrieve the registered CosmosNoSqlVectorStore
            var store = provider.GetService<CosmosNoSqlVectorStore>();
            Assert.NotNull(store);

            // Verify that GetRequiredService<Database>() was called during registration
            // Since we can't directly verify calls inside the lambda, we verify that the Database was resolved
            // by checking that the store's Database property (if accessible) is the mock
            // Alternatively, we can check that the service provider contains the Database instance
            var dbFromStore = store?.Database;
            Assert.Equal(databaseInstance, dbFromStore);
        }
    }
}
```

Note: The above assumes that `CosmosNoSqlVectorStore` exposes its `Database` property publicly. If not, I can verify by other means. Also, since the registration lambda calls `sp.GetRequiredService<Database>()`, and we added a singleton `Database` instance, the registration should resolve that.

